"""Build an offline, screenshot-based 16:9 product walkthrough. No private source data."""
import base64,html,json
from pathlib import Path
from fontTools.ttLib import TTFont
from fontTools import subset
ROOT=Path(__file__).resolve().parents[1]
STEPS=[
 ('材料接入','01-material-entry.png','把材料带入同一个审核工作空间','上传材料包，建立项目与运行记录。','原件与识别结果保留，后续判断可追溯。','现场动作：上传示例材料包，介绍项目、材料与原件页之间的关联。离线演示不会伪造AI审核结果。'),
 ('知识准备','02-knowledge-chunks.png','将制度切成可定位、可引用的知识片段','配置段落切分、片段长度和重叠。','每个片段保留文档版本与原文位置。','现场动作：选择采购付款指引，将长度调整为300、重叠调整为80，重新切片。演示制度有明确标记，不能作为客户正式制度。'),
 ('知识召回','03-knowledge-recall.png','先找到制度依据，再辅助审核判断','输入“付款前需要哪些验收材料”。','展示命中内容、匹配词、来源和排序分数。','实际支持BM25、TF-IDF稀疏向量及混合召回；不是语义Embedding。仅检索已发布文档，审核运行保存命中知识快照。'),
 ('业务口径','05-ontology.png','以业务事件组织实体、属性与关系','统一业务、单据、科目和主体的表达。','本体与映射变更经过草稿和发布管理。','现场动作：展开供应商和业务事件，说明金额、日期、账户等属性及其来源映射。生产实体自动对齐仍需系统接入。'),
 ('模型配置','06-risk-models.png','按业务口径配置“什么算异常”','选择指标、同类群体和历史窗口。','内置稳健统计、滚动基线和Isolation Forest。','现场动作：选择采购单价异常，检查同单位、同业务、同品类分组。统计模型与审核规则分开管理，发布后才对新评测生效。'),
 ('基线评测','07-baseline-evaluation.png','用历史正常区间解释当前异常','展示当前值、历史中位数与参考区间。','逐月向前回测，当前月不进入训练。','现场动作：评测2026-10，展开异常样本。指标来自合成标签，只说明演示流程可计算，不作为真实业务准确率。该模块尚未自动回写三维评分。'),
 ('图谱联查','08-supplier-graph.png','从供应商追到账户和关联业务','定位供应商，展开关联记录及凭证来源。','材料来源、匿名化和演示生成分别标注。','公开截图仅使用演示生成数据。本地另准备了1条历史材料来源记录和34条补充场景。共用账户是一条核查线索，不是违规结论。'),
 ('风险研判','09-risk-list.png','把流程、统计和关联线索放到一起核查','按业务、单位、维度查看待核实事项。','逐条保留分值、命中依据和处理状态。','本页展示既有三维核验策略的计算结果；新增统计评测与来源图谱分别管理，尚未自动融合评分。演示时不要声称已完成生产端到端融合。'),
 ('证据闭环','10-risk-evidence.png','让每次人工判断留下依据','展开事实、检查命中条件并记录研判。','支持台账与研判报告，保留历史快照。','现场动作：查看证据、填写核实人和说明，展示待核实、排除或整改状态。单维命中不能直接确认为风险。'),
 ('运行保障','04-model-diagnostic.png','清楚区分“离线演示”与“模型故障”','显示CLI、登录状态与推理验证状态。','按现场网络条件选择离线演示或真实调用。','当前环境已找到Codex并已登录，但离线演示主动关闭主模型调用。登录成功不等于完成实际推理验证。Jev/StartLux是可选复核服务，需独立配置。')]

def build():
    texts='业财智能合规产品演示从材料到证据从线索到研判业务链路实际页面截图演示数据已明确标记返回产品打开讲稿点击截图放大关闭演示路径交付说明方向键翻页空格下一页讲稿编辑下载下一页上一页'+''.join(''.join(x) for x in STEPS)
    font=TTFont(ROOT/'assets/fonts/wqy-zenhei.ttc',fontNumber=0)
    opt=subset.Options();sub=subset.Subsetter(options=opt);sub.populate(text=texts);sub.subset(font)
    import io
    buffer=io.BytesIO();font.save(buffer);fontdata=base64.b64encode(buffer.getvalue()).decode()
    slides=[]
    slides.append('''<section class="slide cover"><div class="eyebrow">FINANCE / INTELLIGENT COMPLIANCE</div><h1 contenteditable="false">从材料到证据<br>从线索到研判</h1><p class="lead" contenteditable="false">业财智能合规 · 产品业务链路演示</p><div class="flow">材料接入 <i>→</i> 知识辅助 <i>→</i> 风险发现 <i>→</i> 图谱联查 <i>→</i> 人工研判</div><div class="cover-note">v0.7 · 实际产品截图 · 演示数据已标明来源</div><div class="motif"><span>业务</span><span>知识</span><span>证据</span><span>风险</span></div></section>''')
    notes=['建议用8—10分钟讲解。截图来自实际运行页面。公开版本不包含真实供应商名称、账户或原始材料。']
    for i,(stage,file,title,action,outcome,note) in enumerate(STEPS,1):
        data=base64.b64encode((ROOT/'docs/demo-screenshots'/file).read_bytes()).decode()
        slides.append(f'''<section class="slide"><header><span class="eyebrow">业务链路 / {html.escape(stage)}</span><span class="step">{i:02d} / 10</span></header><h2 contenteditable="false">{html.escape(title)}</h2><div class="body"><div class="screen"><img src="data:image/png;base64,{data}" alt="{html.escape(stage)}实际页面截图" tabindex="0"><span class="caption">实际产品页面 · 点击截图放大</span></div><aside><span class="kicker">现场操作</span><h3 contenteditable="false">{html.escape(action)}</h3><div class="rule"></div><span class="kicker">业务结果</span><p contenteditable="false">{html.escape(outcome)}</p><div class="stage-label">{html.escape(stage)}</div></aside></div><footer>业财智能合规 · 产品演示 <span>截图展示实际功能，演示指标不代表生产验收结果</span></footer></section>''');notes.append(note)
    slides.append('''<section class="slide closing"><div class="eyebrow">DEMONSTRATION / DELIVERY</div><h1 contenteditable="false">每一条线索<br>都回到业务与证据</h1><div class="delivery"><div><b>知识可追溯</b><p>原文 → 切片 → 召回 → 运行快照</p></div><div><b>异常可解释</b><p>指标 → 历史基线 → 待核实样本</p></div><div><b>来源可区分</b><p>材料来源 / 匿名化 / 演示生成</p></div></div><p class="closing-note">本地完整版支持配置与计算；在线镜像用于浏览。<br>统计评测与独立来源图谱尚未自动回写三维评分。</p></section>''');notes.append('演示结束。可回到产品继续操作。部署前需对真实数据口径、专家标签、权限、系统接入和现场模型连通进行验证。')
    css='''/* === FIXED 16:9 STAGE === */
:root{--scale:1;--ink:#142e4f;--blue:#246de3;--paper:#f2f6fb}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden}body{background:#102137;color:var(--ink);font-family:DemoSans,sans-serif}.viewport{position:fixed;inset:0;display:grid;place-items:center}.stage{position:absolute;width:1920px;height:1080px;transform:scale(var(--scale));transform-origin:center}.slide{position:absolute;inset:0;width:1920px;height:1080px;visibility:hidden;opacity:0;pointer-events:none;transition:opacity .3s;background:var(--paper);padding:66px 80px}.slide.active{visibility:visible;opacity:1;pointer-events:auto}header{display:flex;justify-content:space-between;align-items:center}.eyebrow{font-size:20px;letter-spacing:4px;color:var(--blue)}.step{font-size:24px;color:#7186a0}h2{font-size:53px;font-weight:600;line-height:1.25;margin:24px 0 34px}h1{font-size:102px;line-height:1.3;font-weight:600;margin:74px 0 32px;letter-spacing:-2px}.lead{font-size:37px;color:#486281}.body{display:grid;grid-template-columns:1280px 1fr;gap:55px;align-items:start}.screen{position:relative;border:1px solid #d2dfed;border-radius:12px;background:white;box-shadow:0 20px 60px #17365a12;overflow:hidden}.screen img{width:1280px;height:800px;object-fit:contain;display:block;cursor:zoom-in}.caption{position:absolute;bottom:0;right:0;font-size:14px;background:#173458e6;color:white;padding:5px 10px}aside{padding:25px 0}.kicker{font-size:21px;letter-spacing:3px;color:#7287a0}aside h3{font-size:37px;font-weight:500;line-height:1.55;margin:22px 0 38px}aside p{font-size:30px;line-height:1.7}.rule{height:2px;background:#d5e1ef;margin-bottom:34px}.stage-label{margin-top:55px;border-left:5px solid var(--blue);padding:12px 20px;color:var(--blue);font-size:23px}footer{position:absolute;bottom:20px;left:80px;right:80px;font-size:16px;color:#6e829b;display:flex;justify-content:space-between}.cover,.closing{background:linear-gradient(115deg,#f7faff 0%,#eef4fc 72%,#dce9fa 100%)}.cover .flow{position:absolute;bottom:165px;font-size:29px;display:flex;gap:27px;align-items:center}.flow i{font-style:normal;color:#90a8c7}.cover-note{position:absolute;bottom:70px;font-size:22px;color:#637d9c}.motif{position:absolute;right:130px;top:205px;width:470px;height:470px;border:2px solid #acc9f1;border-radius:50%;display:grid;grid-template-columns:1fr 1fr;gap:46px;padding:48px;transform:rotate(-8deg)}.motif span{border-radius:50%;display:grid;place-items:center;background:white;box-shadow:0 15px 40px #123c6f18;font-size:35px;color:#2764b1;transform:rotate(8deg)}.motif span:nth-child(3){background:#246de3;color:white}.closing h1{margin-top:50px}.delivery{display:flex;gap:60px;margin-top:58px}.delivery>div{border-top:3px solid #246de3;padding-top:25px;min-width:480px}.delivery b{font-size:34px;font-weight:500}.delivery p{font-size:23px;color:#5c7593}.closing-note{font-size:25px;line-height:1.8;margin-top:60px;color:#5c7593}/* === NAVIGATION & ACCESSIBILITY === */.controls{position:fixed;bottom:12px;right:18px;display:flex;align-items:center;gap:8px;z-index:30;background:#102137cc;border-radius:8px;padding:6px}button,.controls a{font:14px DemoSans,sans-serif;cursor:pointer;border:1px solid #6d849e;color:white;background:transparent;border-radius:5px;padding:7px 11px;text-decoration:none}.controls span{color:white;font:14px sans-serif;padding:0 10px}button:focus-visible,img:focus-visible{outline:3px solid #ffbb56}.notes{position:fixed;bottom:65px;right:18px;background:#102137f2;color:white;max-width:540px;padding:24px;line-height:1.8;font-size:18px;z-index:35;border:1px solid #829ab7;border-radius:10px}.notes[hidden]{display:none}.zoom{position:fixed;inset:0;background:#0b1d32f5;z-index:60;display:grid;place-items:center}.zoom[hidden]{display:none}.zoom img{max-width:96vw;max-height:94vh;object-fit:contain}.zoom button{position:absolute;right:15px;top:15px;background:#123653}body.editing [contenteditable]{outline:2px dashed #246de3}@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}/* === PRINT: ONE PAGE PER SLIDE === */@page{size:1920px 1080px;margin:0}@media print{html,body{height:auto;overflow:visible;background:white}.viewport{position:static;display:block}.stage{position:static;transform:none!important;height:auto}.slide{position:relative;visibility:visible!important;opacity:1!important;break-after:page;page-break-after:always;transition:none}.slide:last-child{break-after:auto}.controls,.notes,.zoom{display:none!important}}
'''
    js='''/* === SLIDE CONTROLLER === */
const slides=[...document.querySelectorAll('.slide')],notes=NOTES;let index=0;const scale=()=>document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1920,innerHeight/1080));addEventListener('resize',scale);scale();function show(i){index=Math.max(0,Math.min(slides.length-1,i));slides.forEach((s,n)=>s.classList.toggle('active',n===index));document.querySelector('#count').textContent=(index+1)+' / '+slides.length;document.querySelector('.notes').textContent=notes[index];}show(0);const close=()=>document.querySelector('.zoom').hidden=true;document.querySelector('#prev').onclick=()=>show(index-1);document.querySelector('#next').onclick=()=>show(index+1);document.querySelector('#notes').onclick=()=>document.querySelector('.notes').hidden=!document.querySelector('.notes').hidden;function edit(){const on=document.body.classList.toggle('editing');document.querySelectorAll('[contenteditable]').forEach(e=>e.contentEditable=on)}function save(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['<!doctype html>'+document.documentElement.outerHTML],{type:'text/html'}));a.download='业财智能合规-产品演示.html';a.click();URL.revokeObjectURL(a.href)}document.querySelector('#edit').onclick=edit;document.querySelector('#save').onclick=save;document.querySelector('.zoom button').onclick=close;document.querySelectorAll('.screen img').forEach(img=>{const zoom=()=>{document.querySelector('.zoom img').src=img.src;document.querySelector('.zoom').hidden=false};img.onclick=zoom;img.onkeydown=e=>{if(e.key==='Enter')zoom()}});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();save();return}if(e.key==='Escape'){close();return}if(e.target.isContentEditable)return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(index+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(index-1)}if(e.key.toLowerCase()==='n')document.querySelector('#notes').click();if(e.key.toLowerCase()==='e')edit()});let x=0;document.addEventListener('touchstart',e=>x=e.touches[0].clientX,{passive:true});document.addEventListener('touchend',e=>{const d=e.changedTouches[0].clientX-x;if(Math.abs(d)>60)show(index+(d<0?1:-1))},{passive:true});
'''.replace('NOTES',json.dumps(notes,ensure_ascii=False))
    output='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>业财智能合规 · 产品业务链路演示</title><style>@font-face{font-family:DemoSans;src:url(data:font/ttf;base64,'+fontdata+') format("truetype");font-display:swap}'+css+'</style></head><body><div class="viewport"><main class="stage">'+''.join(slides)+'</main></div><nav class="controls" aria-label="演示控制"><a href="./index.html">返回产品</a><button id="prev" aria-label="上一页">←</button><span id="count"></span><button id="next" aria-label="下一页">→</button><button id="notes">讲稿 N</button><button id="edit">编辑 E</button><button id="save">下载</button></nav><aside class="notes" hidden></aside><div class="zoom" hidden><img alt="放大的产品截图"><button>关闭 Esc</button></div><script>'+js+'</script></body></html>'
    p=ROOT/'static/demo.html';p.write_text(output);print(p, len(slides),'slides',p.stat().st_size,'bytes')
if __name__=='__main__':build()
